#define MAX_STEPS 500

vec3 ori() {
    vec2 m = iMouse.xy/iResolution.xy;
    vec3 ro = vec3(1);
    ro += 0.1 * iTime * vec3(1, 0.9, 0.95);
    //vec3 ro = vec3(0,1,-1);
    //ro.yz *= rot(-m.y*3.14+1.);
    //ro.xz *= rot(-m.x*6.2831);
    return ro;
}

// Map noise values [0,1]^3->[0,1]
float map(vec3 p) {
    float sc = 0.3;//2. - 1.7 * tanh(0.2 * iTime);
    vec3 q = texture(iChannel0, sc * p).rgb;
    float d = dot(q,q);
    return d * d;
}

// Map noise values [0,1]^3->[0,1]^3 (unused)
vec3 map2(vec3 p) {
    vec3 q = texture(iChannel0, 0.3 * p).rgb;
    return pow(q, vec3(4));
}

// (not traditional raymarching)
vec2 march(vec3 ro, vec3 rd) {	
    float d = 0.;
    int steps = 0;

    for(int i = 0; i < MAX_STEPS; i++) {
       vec3 p = ro + rd * d;

       // dd reads noise from 3D texture, value in [0,1]
       float dd = map(p);

       // hide overstepping with noise (slow)
       // dd *= 0.9 + 0.1 * hash(p.x, hash(p.y, p.z));

       // smaller increments -> less overstepping      
       d += 0.01 * dd;

       // maybe replace c with function based on distance from ro?
       // if p is close to ro, set threshold to 0. idk
       float c = .5 + .5 * thc(4., 10. * d + p.y - iTime);

       // threshold for where to draw noise
       // (dd > 1.5), (abs(dd - 0.5)< 0.004) look cool
       if (dd < mix(0.1, 0.18, c)) {
           steps = i;
           break;
       }
    }

    return vec2(d, steps);
}

vec3 dir(vec2 uv, vec3 p, vec3 l, float z) {
    vec3 f = normalize(l-p),
        r = normalize(cross(vec3(0,1,0), f)),
        u = cross(f,r),
        c = f*z,
        i = c + uv.x*r + uv.y*u,
        d = normalize(i);
    return d;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.y;

    vec3 ro = ori();    
    vec3 rd = dir(uv, ro, vec3(0), 1.5);

    // m.x = distance
    // m.y = number of steps
    vec2 m = march(ro, rd);

    vec3 p = ro + m.x * rd;

    vec3 col = vec3(.9,.1,.1);

    //float y = exp(-20.*(.5+.5*cos(80. * p.x + iTime)));    
    vec3 col1 = vec3(1,.5,.2);
    //vec3 col2 = clamp(col1 + y, 0., 1.);
    //col = mix(col, col2, 1.-exp(-0.01 * m.y));

    // surface colors
    col *= pal(map(p + 0.02) - 0.2 * iTime, 0.5 * vec3(0,1,2)/3.);

    // fog
    col = mix(col, col1, 1.-clamp(exp(1.-1.4*m.x), 0., 1.));

    // gamma correction
    col = pow(col, vec3(1./2.2));	

    fragColor = vec4(col,1.0);
}

